const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const badge=(text,kind=text)=>{const labelKey=String(text).toLowerCase().replace(/[\s-]+/g,'_'),mockConnected=['mock_configured','mock_connected'].includes(labelKey);const statusClass=mockConnected?'mock_configured badge-success':String(kind).toLowerCase().replace(/[\s-]+/g,'_');return `<span class="badge ${e(statusClass)}">${e(mockConnected?'Mock connected':displayLabel(text))}</span>`;};
const date=v=>v?new Date(v).toLocaleString('en-GB',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Not recorded';
const ago=v=>v?date(v):'Not measured';
