const empty=(title,text,action='')=>`<div class="empty"><div class="empty-icon">${icon('audit')}</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
function toast(s){if(dialog.open){dialogNotice(s,false);return;}toastEl.textContent=s;toastEl.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.style.display='none',5500)}
const accountIdentity=user=>JSON.stringify([user.id,user.role,user.tenant]);
async function api(url,options={}){
 const mutation=options.method&&options.method!=='GET'&&url!=='/api/login';
 let identity;
 if(mutation&&state.user){
  identity=accountIdentity(state.user);
  // Cookies are shared across tabs; never submit under a different account.
  const sessionResponse=await fetch('/api/me',{cache:'no-store'});
  if(!sessionResponse.ok){if(sessionResponse.status===401){clearSession();login()}throw Error('Your session could not be verified. Sign in again before continuing.')}
  const session=await sessionResponse.json();
  if(!state.user||accountIdentity(state.user)!==identity||accountIdentity(session.user)!==identity){clearSession();login();throw Error('The signed-in account changed in another tab. Sign in again to continue with the intended account.')}
  state.csrf=session.csrf;
 }
 const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers,'X-CSRF-Token':state.csrf,...(identity?{'X-GeoBridge-Account':identity}:{})},body:options.body===undefined?undefined:JSON.stringify(options.body)});
 const data=await r.json();
 if(!r.ok){
  if((r.status===401&&url!=='/api/login')||data.code==='SESSION_CHANGED'){clearSession();login()}
  throw Object.assign(Error(data.error||'Request failed'),{fieldErrors:data.fieldErrors});
 }
 return data;
}

function modal(title,body){document.querySelector('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button(icon('close'),'close','quiet','aria-label="Close dialog"')}</div><div class="dialog-content"><div id="dialog-message" class="dialog-message" role="alert" tabindex="-1" hidden></div>${body}</div>`;dialog.showModal()}
const summaryVerdictOrder=['PASS','FAIL','BLOCKED','NEEDS_REVIEW','NOT_ASSESSED','NOT_APPLICABLE'];
const verdictOrder=['FAIL','BLOCKED','NEEDS_REVIEW','NOT_ASSESSED','NOT_APPLICABLE','PASS'];
const verdictLabels={PASS:'Passed',FAIL:'Failed',BLOCKED:'Blocked',NEEDS_REVIEW:'Needs review',NOT_ASSESSED:'Not assessed',NOT_APPLICABLE:'Not applicable'};
function activeNavigation(){if(state.page==='connection-detail')return 'connections';return state.page==='detail'?(state.run?.kind==='platform'?'diagnostics':'audit'):state.page;}
function connectionBadge(c){const target=(state.availability||[]).find(t=>t.id===c.id||'mock-'+t.id===c.id||t.connectionId===c.id);const health=target?.report?.currentStatus;if(health==='down')return `<span class="badge connection-down" title="Latest monitoring probe reported this connection down">Unavailable</span>`;return badge(c.status,c.status==='mock_configured'?'mock_configured':c.status);}
function resultCounts(r){if(!Array.isArray(r.results)||!r.results.length)return r.counts||{};return r.results.reduce((counts,f)=>{counts[f.verdict]=(counts[f.verdict]||0)+1;return counts;},{});}
function groupedFindings(r){const findings=(r.results||[]).filter(f=>state.filter==='all'||f.layer===state.filter);if(!findings.length)return `<div class="card">${empty('No results in this layer','The worker has not recorded any matching checks.')}</div>`;const order=[...verdictOrder,...new Set(findings.map(f=>f.verdict).filter(v=>!verdictOrder.includes(v)))];return `<div class="finding-groups">${order.map(verdict=>{const items=findings.filter(f=>f.verdict===verdict);if(!items.length)return '';return `<section class="card verdict-group ${e(String(verdict).toLowerCase())}" id="verdict-${e(verdict)}" aria-labelledby="verdict-heading-${e(verdict)}"><div class="card-head"><h2 id="verdict-heading-${e(verdict)}" tabindex="-1">${e(verdictLabels[verdict]||verdict)} <span class="group-count">${items.length}</span></h2>${badge(verdict)}</div>${items.map(f=>`<div class="finding" role="button" tabindex="0" data-finding="${e(f.id)}" aria-label="Open finding: ${e(f.title)}"><div style="color:var(--teal)">${icon(f.layer==='security'?'gate':'audit')}</div><div><h3>${e(f.title)}</h3><p>${e(f.observed)}</p><small class="subtle">${e(f.ruleId||f.id)} · ${e(f.basis||'Selected rule')}${f.section?' · §'+e(f.section):''}</small></div>${badge(f.verdict)}</div>`).join('')}</section>`;}).join('')}</div>`;}
function motionBehavior(){return globalThis.window?.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';}
function jumpVerdict(verdict){if(!verdictOrder.includes(verdict))return;state.filter='all';render();const section=document.querySelector('#verdict-'+verdict);if(!section)return;document.querySelector('#verdict-heading-'+verdict)?.focus({preventScroll:true});section.scrollIntoView({behavior:motionBehavior(),block:'start'});}
let topScrollFrame=null;
function smoothTop(){const win=globalThis.window;if(!win)return;if(topScrollFrame!==null)win.cancelAnimationFrame(topScrollFrame);const start=win.scrollY||document.scrollingElement?.scrollTop||0;if(start<=0)return;const began=win.performance.now(),duration=360;const tick=now=>{const progress=Math.min(1,(now-began)/duration),eased=1-Math.pow(1-progress,3);win.scrollTo({top:start*(1-eased),left:0,behavior:'instant'});if(progress<1)topScrollFrame=win.requestAnimationFrame(tick);else topScrollFrame=null;};topScrollFrame=win.requestAnimationFrame(tick);}

function updateScrollTop(){const control=document.querySelector('.scroll-top');if(control)control.hidden=!state.user||(globalThis.window?.scrollY||0)<500;}
globalThis.window?.addEventListener?.('scroll',updateScrollTop,{passive:true});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches?.('.finding[data-finding],tr[data-run]')){ev.preventDefault();ev.target.click();}});
function displayFilterDate(iso){return /^\d{4}-\d{2}-\d{2}$/.test(iso||'')?iso.slice(8,10)+'/'+iso.slice(5,7)+'/'+iso.slice(0,4):'';}
function parseFilterDate(value){if(!value.trim())return '';const m=/^(\d{2})\/(\d{2})\/(\d{4})$/.exec(value.trim());if(!m)return null;const [,d,mo,y]=m,iso=y+'-'+mo+'-'+d,dt=new Date(iso+'T12:00:00Z');return Number.isFinite(dt.getTime())&&dt.toISOString().slice(0,10)===iso?iso:null;}
function historyDateInput(key,value){return `<div class="history-date-field"><input type="text" id="history-${key}" data-history-date="${key}" placeholder="DD/MM/YYYY" aria-label="${key==='from'?'Start':'End'} date, DD/MM/YYYY" inputmode="numeric" maxlength="10" value="${e(displayFilterDate(value))}"><button type="button" data-action="history-calendar" data-key="${key}" aria-label="Choose ${key==='from'?'start':'end'} date">${icon('clock')}</button><input type="date" id="history-${key}-picker" class="history-native-picker" data-history-filter="${key}" tabindex="-1" aria-hidden="true" value="${e(value||'')}"></div>`;}
function runDay(run){const d=new Date(run.startedAt||run.createdAt);if(!Number.isFinite(d.getTime()))return '';return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function historyBank(run){return run.connectionId||'saved-responses';}
function historyBankName(id){return state.workspace.connections.find(c=>c.id===id)?.name||(id==='saved-responses'?'Saved response reviews':id);}
function selectHistoryRuns(runs,filters){return runs.filter(r=>(!filters.bank||historyBank(r)===filters.bank)&&(!filters.from||runDay(r)>=filters.from)&&(!filters.to||(runDay(r)&&runDay(r)<=filters.to))).sort((a,b)=>Date.parse(b.startedAt||b.createdAt)-Date.parse(a.startedAt||a.createdAt));}
function auditHistory(runs){const f=state.historyFilters||{bank:'',from:'',to:'',group:'none'},banks=[...new Set(runs.map(historyBank))].sort((a,b)=>historyBankName(a).localeCompare(historyBankName(b))),invalid=f.from&&f.to&&f.from>f.to,selected=invalid?[]:selectHistoryRuns(runs,f);const control=(id,label,body)=>`<div class="field"><label for="history-${id}">${label}</label>${body}</div>`;
 const filters=`<div class="history-filters">${control('bank','Bank / connection',`<select id="history-bank" data-history-filter="bank"><option value="">All banks</option>${banks.map(id=>`<option value="${e(id)}" ${f.bank===id?'selected':''}>${e(historyBankName(id))}</option>`).join('')}</select>`)}${control('from','Run date · from',historyDateInput('from',f.from))}${control('to','Run date · to',historyDateInput('to',f.to))}${control('group','Group by',`<select id="history-group" data-history-filter="group">${[['none','Newest first'],['bank','Bank / connection'],['date','Run date']].map(([k,label])=>`<option value="${k}" ${(f.group||'none')===k?'selected':''}>${label}</option>`).join('')}</select>`)}${button('Reset','reset-history','quiet')}</div><div class="history-result-count" role="status">${invalid?'Choose an end date on or after the start date.':`${selected.length} of ${runs.length} audits · dates use your local time`}</div>`;
 if(!selected.length)return filters+empty('No matching audits',invalid?'Correct the date range to see audit history.':'Change the bank or date filters, or reset to see all audits.');
 if(!['bank','date'].includes(f.group))return filters+runTable(selected);
 const groups=new Map();for(const run of selected){const key=f.group==='bank'?historyBank(run):(runDay(run)||'Date unavailable');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(run);}const keys=[...groups.keys()].sort((a,b)=>f.group==='bank'?historyBankName(a).localeCompare(historyBankName(b)):b.localeCompare(a));return filters+keys.map(key=>`<section class="history-group"><h3>${e(f.group==='bank'?historyBankName(key):(displayFilterDate(key)||key))} <span class="group-count">${groups.get(key).length}</span></h3>${runTable(groups.get(key))}</section>`).join('');}

function displayLabel(value){const text=String(value??'');const names={mock_configured:'Mock connected',mock_connected:'Mock connected',not_connected:'Setup required',mock_http:'Mock HTTP',synthetic_mock:'Mock environment',mock_supported:'Supported in mock',sandbox:'Sandbox',pending:'Setup pending',unknown:'Not verified',bank_demo:'Bank demo','bank-demo':'Bank demo','xs2a-0.8':'XS2A 0.8','ofa-ais':'Open Finance AIS',not_uploaded:'Not uploaded'};return names[text]||text.replace(/[_-]+/g,' ');}
function dialogNotice(message,isError=true){const box=document.querySelector('#dialog-message');if(!box)return false;box.textContent=String(message);box.hidden=false;box.className='dialog-message '+(isError?'is-error':'is-info');box.setAttribute('role',isError?'alert':'status');box.focus?.({preventScroll:true});box.scrollIntoView?.({block:'nearest',behavior:'instant'});return true;}
function showError(message){if(dialog.open&&dialogNotice(message,true))return;toast(message);}
function profileLabel(id){return state.workspace?.profiles?.find(p=>p.id===id)?.name||displayLabel(id);}

function comparisonResult(result){const changes=Array.isArray(result.changes)?result.changes:[],run=id=>state.workspace.runs.find(r=>r.id===id),before=run(result.before),after=run(result.after),nowPass=changes.filter(c=>c.after==='PASS').length,nowFail=changes.filter(c=>c.after==='FAIL').length;const auditCard=(label,r,id)=>`<div class="comparison-audit"><small>${label}</small><strong>${e(r?.name||'Audit')}</strong><span>${e(date(r?.finishedAt||r?.createdAt))}</span></div>`;
 return `<section class="comparison-result space"><header><h3 id="comparison-heading" tabindex="-1">${changes.length?changes.length+' check result'+(changes.length===1?'':'s')+' changed':'No matched verdict changes'}</h3><p>${e(profileLabel(result.profile))} · ${e(displayLabel(result.evidenceMode))}</p></header><div class="comparison-audits">${auditCard('Earlier audit',before,result.before)}${auditCard('Later audit',after,result.after)}</div><div class="comparison-stats"><div><b>${changes.length}</b><span>Changed verdicts</span></div><div class="comparison-passing"><b>${nowPass}</b><span>Changed to pass</span></div><div class="comparison-failing"><b>${nowFail}</b><span>Changed to fail</span></div></div>${result.rulesetChanged?'<div class="comparison-warning"><b>Ruleset changed</b><p>These audits used different rulesets. A verdict change may reflect a rule change rather than a bank change.</p></div>':''}<div class="comparison-context"><span>Ruleset: <b>${result.rulesetChanged?'Changed':'Unchanged'}</b></span><span>Evidence: <b>${result.evidenceChanged?'Changed':'Same hash'}</b></span></div>${changes.length?`<div class="table-wrap comparison-table"><table><thead><tr><th>Check</th><th>Earlier result</th><th>Later result</th></tr></thead><tbody>${changes.map(c=>`<tr><td><b>${e(c.title||c.id)}</b></td><td>${badge(c.before)}</td><td>${badge(c.after)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="comparison-empty">Matching checks kept the same verdict. This does not establish that every request, measurement or checked requirement was identical.</div>'}<p class="comparison-scope">Only matching check identifiers and observations are compared. Added or removed checks are not included. Use equivalent workloads and applicable rules.</p><details class="comparison-technical"><summary>Technical details (JSON)</summary><pre class="code">${e(JSON.stringify(result,null,2))}</pre></details></section>`;
}

function head(eyebrow,title,description,actions=''){return `<header class="pagehead"><div><h1>${title}</h1></div><div class="buttons">${actions}</div></header>`}
function notice(title,text,amber=false){return `<div class="notice ${amber?'amber':''}">${icon('info')}<div><b>${title}</b><p>${text}</p></div></div>`}
const rolePolicies={
 operator:{title:'Operator workspace',home:'overview',pages:['overview','audit','connections','explorer','oversight','monitor','reports','standards','gate','diagnostics','activity']},
 bank:{title:'Bank engineer workspace',home:'overview',pages:['overview','audit','monitor','reports','standards','gate','activity']},
 tpp:{title:'TPP developer workspace',home:'overview',pages:['overview','explorer','activity']},
 reviewer:{title:'NBG Reviewer workspace',home:'oversight',pages:['overview','oversight','audit','connections','monitor','reports','standards','gate','activity']}

};
const policy=()=>rolePolicies[state.user?.role]||{title:'Restricted workspace',home:'activity',pages:['activity']};
const roleNav=()=>policy().pages.map(key=>nav.find(([id])=>id===key)).filter(Boolean);
function activateSession(result){state.measurementFilters={connection:'',operation:''};state.connectionId=null;state.measurementCollapsed={};state.historyFilters={bank:'',from:'',to:'',group:'none'};state.user=result.user;state.csrf=result.csrf;state.workspace=null;state.gringott=null;state.run=null;state.filter='all';state.page=policy().home;}
function clearSession(){state.measurementFilters={connection:'',operation:''};state.connectionId=null;state.measurementCollapsed={};state.historyFilters={bank:'',from:'',to:'',group:'none'};state.user=null;state.csrf='';state.gringott=null;state.availability=[];state.workspace=null;state.run=null;state.filter='all';state.page=null;if(dialog.open)dialog.close();}
function navigate(page){state.menuOpen=false;state.page=policy().pages.includes(page)?page:policy().home;state.filter='all';render();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'});}
const canRun=()=>['operator','bank','reviewer'].includes(state.user.role);
const canConfigure=()=>['operator','bank'].includes(state.user.role);
const canGate=()=>['operator','reviewer'].includes(state.user.role);
const canReview=()=>['operator','reviewer'].includes(state.user.role);
const nav=[['diagnostics','System diagnostics'],['overview','Overview'],['audit','Audit center'],['connections','Connections'],['explorer','TPP explorer'],['oversight','Oversight dashboard'],['monitor','Monitoring'],['reports','Reports'],['standards','Standards & rules'],['gate','Release gates'],['activity','Activity log']];
function setMenu(open){
 state.menuOpen=open;
 const shell=document.querySelector('.workspace-shell'),toggle=document.querySelector('.topbar .menu-toggle'),menu=document.querySelector('#workspace-menu');
 if(!shell)return;
 shell.classList.toggle('menu-open',open);menu.inert=!open;document.querySelectorAll('.menu-toggle').forEach(control=>{control.setAttribute('aria-expanded',String(open));control.setAttribute('aria-label',open?'Close menu':'Open menu')});
 if(!open&&arguments[1]!==false)toggle?.focus();
}
