function connections(){if(state.user.role!=='operator')return mockBankConnections();return head('','Connections','',canConfigure()?button(icon('plus')+' Register connection','new-connection','primary'):'')+`<p class="connections-intro">Select a connection to view its details and available actions.</p><div class="connection-list">${state.workspace.connections.map(c=>`<button type="button" class="connection-list-card" data-action="open-connection" data-id="${e(c.id)}" aria-label="View ${e(c.name)}"><span class="connection-card-name">${e(c.name)}</span>${connectionBadge(c)}<span class="connection-card-arrow" aria-hidden="true">${icon('chevron')}</span></button>`).join('')||`<div class="card">${empty('No connections in your scope','Register an authorized sandbox connection to get started.')}</div>`}</div>`;}
function connectionDetail(){const c=state.workspace.connections.find(c=>c.id===state.connectionId);if(!c)return empty('Connection unavailable','This connection is no longer available in your workspace.',button('Back to connections','nav-connections'));
 const profile=state.workspace.profiles.find(p=>p.id===c.profile)?.name||displayLabel(c.profile),value=(label,text,mono=false)=>`<div><dt>${label}</dt><dd class="${mono?'connection-value-mono':''}">${e(text||'Not supplied')}</dd></div>`,configured=c.status==='mock_configured';
 return head('',e(c.name),'',button('Back to connections','nav-connections')+(canRun()?button(configured?'Run HTTP audit':'Check readiness','readiness','primary',`data-id="${e(c.id)}"`):''))+`<div class="connection-detail-status">${connectionBadge(c)}<p>${configured?'Configured for synthetic HTTP requests. Check readiness before running an audit.':'Registered connection. Adapter setup and connectivity verification may still be required.'}</p></div><div class="connection-detail-grid"><section class="card"><div class="card-head"><h2>Connection overview</h2></div><dl class="connection-facts">${value('Connection name',c.name)}${value('Environment',displayLabel(c.environment))}${value('Workspace',displayLabel(c.tenant))}${value('Standards profile',profile)}</dl></section><section class="card"><div class="card-head"><h2>API endpoint</h2></div><dl class="connection-facts">${value('Base URL',c.baseUrl||'Not supplied',true)}${value('Authorization',configured?'Simulated consent through the configured adapter':'Requires setup')}</dl><p class="connection-card-note">Registering a URL does not by itself authorize access or create an adapter.</p></section><section class="card"><div class="card-head"><h2>Supported operations</h2></div><div class="connection-capabilities">${Object.entries(c.capabilities||{}).map(([operation,status])=>`<div><span>${e(displayLabel(operation))}</span>${badge(displayLabel(status),status==='mock_supported'?'mock_configured':status)}</div>`).join('')||'<p>No capabilities recorded.</p>'}</div></section><section class="card"><div class="card-head"><h2>API specification</h2>${badge(c.specHash?'Attached':'Not uploaded',c.specHash?'pass':'unknown')}</div><div class="pad"><p>${c.specHash?'A specification is attached for static contract review.':'No specification is attached for static review. Configured mock HTTP audits can still fetch the mock contract during a run.'}</p>${canConfigure()?`<div class="buttons space">${button('Upload OpenAPI','upload-spec','small',`data-id="${e(c.id)}"`)}${c.specHash?button('Review specification','run-spec','small',`data-id="${e(c.id)}"`):''}</div>`:''}</div></section></div><details class="card connection-technical space"><summary>Technical identifiers</summary><dl class="connection-facts">${value('Connection ID',c.id,true)}${value('Adapter version',c.adapter||'Not configured',true)}${value('Profile ID',c.profile,true)}${value('Specification hash',c.specHash||'Not uploaded',true)}</dl></details>`;
}


