function explorer(){const catalog=state.workspace.catalog||[];return head('ONE CONTRACT · EXPLICIT ADAPTERS','TPP explorer','Understand the common response format before connecting an authorized bank.')+notice('Test data and mapping','Use mock connections for HTTP requests or preview how JSON responses map to the common format. Real-bank data is not connected.')+gringottExplorer()+`<div class="card space"><div class="card-head"><div><h2>Supported connections</h2><p>Published capabilities only. Private bank configuration is not shared.</p></div></div>${catalog.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Connection</th><th>Status</th><th>Capabilities</th></tr></thead><tbody>${catalog.map(c=>`<tr><td>${e(c.name)}</td><td>${connectionBadge(c)}</td><td>${Object.entries(c.capabilities||{}).map(([k,v])=>displayLabel(k)+': '+displayLabel(v)).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`:empty('No published connections yet','Bank adapters and authorization must be verified before live operations become available.')}</div><div class="grid two space"><div class="card"><div class="card-head"><div><h2>Common contract preview</h2><p>Validate an API response and convert it to the common format.</p></div>${badge('Synthetic preview')}</div><div class="pad"><div class="field"><label for="mapping-operation">Operation</label><select id="mapping-operation"><option value="balances">Get balances</option><option value="accounts">List accounts</option><option value="transactions">List transactions</option></select></div><div class="field"><label for="mapping-json">Original synthetic response</label><textarea id="mapping-json" style="min-height:290px">${e(JSON.stringify(mappingSamples.balances,null,2))}</textarea></div><div class="buttons">${button(icon('play')+' Validate & normalize','normalize','primary')}${button('Insert missing-currency fault','mapping-fault','small')}</div></div></div><div class="card"><div class="card-head"><div><h2>GeoBridge response</h2><p>Normalized response or validation errors.</p></div></div><div class="pad" id="mapping-result">${empty('No mapping result yet','Enter a response and select Validate & normalize.')}</div></div></div><div class="card space"><div class="card-head"><h2>Bank API access</h2>${badge('Not connected','blocked')}</div><div class="pad"><div class="grid two"><div><h3>Proposed common endpoints</h3><a class="btn small" href="/api/contract" target="_blank" rel="noopener">Common OpenAPI JSON</a><pre class="code light">GET /bridge/v1/connections
GET /bridge/v1/connections/{id}/accounts
GET /bridge/v1/connections/{id}/accounts/{id}/balances
GET /bridge/v1/connections/{id}/accounts/{id}/transactions</pre></div><div><h3>Required connection setup</h3><p>Each connection needs a bank-specific adapter, the TPP identity, supported permissions and an authoritative valid consent. Current bank requests return <code>BANK_NOT_CONNECTED</code>.</p><div class="spacer"></div>${['tpp','operator'].includes(state.user.role)?button('Check bank API response','bridge-check'):badge('TPP login required')}</div></div><div id="bridge-result"></div></div></div>`}
function monitoring(){const w=state.workspace;const captures=w.runs.filter(r=>r.status==='completed'&&r.metrics?.some(m=>m.attempts));return head('MEASURE WHAT YOU ACTUALLY OBSERVE','Monitoring','Schedules, observation windows and per-operation measurements—with clear freshness.',canRun()?button(icon('plus')+' Add schedule','new-schedule','primary'):'')+availabilityPanel()+`<div class="grid three">${metric('Bank probe availability','—','No live bank probe history in your scope','monitor',false,'#monitor-availability')}${metric('Bank response time','—','No live latency observations','monitor',false,'#monitor-measurements')}${metric('Active schedules',w.schedules.length,'Runs while the local server is running','clock',false,canRun()?'#monitor-schedules':'#monitor-observations')}</div><div class="card space"><div class="card-head"><div><h2 id="monitor-observations" tabindex="-1">Observation history</h2><p>Unknown intervals stay grey. No monthly uptime is inferred.</p></div>${badge('No live observations')}</div><div class="pad"><div class="timeline">${Array.from({length:60},()=>'<i title="No observation"></i>').join('')}</div><div class="legend"><span class="good">Successful probe</span><span class="bad">Failed probe</span><span>No observation</span></div><div class="spacer"></div><p class="smalltext">Connect a bank adapter before enabling actual probes. Replaying captured evidence does not create new bank availability observations.</p></div></div>${canRun()?`<div class="card space"><div class="card-head"><h2 id="monitor-schedules" tabindex="-1">Scheduled jobs</h2></div>${w.schedules.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Job</th><th>Interval</th><th>Next run</th><th>Last result</th><th></th></tr></thead><tbody>${w.schedules.map(s=>`<tr><td>${e(s.label)}</td><td>${s.minutes} min</td><td>${date(s.nextRun)}</td><td>${e(s.lastError|| (s.lastRun?'Scheduled successfully':'Waiting'))}</td><td>${canRun()?button('Remove','delete-schedule','small',`data-id="${s.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('No schedules yet','Schedule a mock bank API audit or review saved response evidence.')}</div>`:''}${measurementPanels(captures)}`}


function measurementPanels(captures){
 const f=state.measurementFilters||{connection:'',operation:''};
 const name=id=>id==='imported'?'Imported responses':state.workspace.connections.find(c=>c.id===id)?.name||id;
 const ids=[...new Set(captures.map(r=>r.connectionId||'imported'))];
 const selected=captures.filter(r=>!f.connection||(r.connectionId||'imported')===f.connection);
 const rows=selected.flatMap(r=>(r.metrics||[]).filter(m=>m.attempts&&(!f.operation||m.operation===f.operation)).map(m=>({r,m})));
 const imported=selected.filter(r=>r.evidenceMode!=='mock_http'&&(r.metrics||[]).some(m=>m.attempts&&(!f.operation||m.operation===f.operation)));
 const select=(id,label,values,value)=>'<div class="field"><label for="'+id+'">'+label+'</label><select id="'+id+'"><option value="">All '+label.toLowerCase()+'s</option>'+values.map(([v,t])=>'<option value="'+e(v)+'" '+(value===v?'selected':'')+'>'+e(t)+'</option>').join('')+'</select></div>';
 const section=(id,title,count,content)=>'<details class="card space measurement-section" data-measurement-section="'+id+'" '+(state.measurementCollapsed?.[id]?'':'open')+'><summary><span>'+title+'</span><span class="badge">'+count+'</span>'+icon('chevron')+'</summary><div class="measurement-scroll" tabindex="0" role="region" aria-label="'+title+'">'+content+'</div></details>';
 const table=rows.length?'<table><thead><tr><th>Connection / run</th><th>Profile / mode</th><th>Operation</th><th>Attempts</th><th>p50 ms</th><th>p95 ms</th></tr></thead><tbody>'+rows.map(({r,m})=>'<tr><td>'+e(name(r.connectionId||'imported'))+'<small>'+e(r.name)+'</small></td><td>'+e(r.profile)+'<small>'+e(r.evidenceMode)+'</small></td><td>'+e(m.operation)+'</td><td>'+m.attempts+'</td><td>'+e(m.p50??'—')+'</td><td>'+e(m.p95??'Insufficient samples')+'</td></tr>').join('')+'</tbody></table>':empty(captures.length?'No measurements match these filters':'No response measurements yet',captures.length?'Change or reset the filters.':'Run a configured bank audit or import timestamped response samples.');
 return '<div id="monitor-measurements" tabindex="-1" class="measurement-filters card pad space">'+select('measurement-connection','Connection',ids.map(id=>[id,name(id)]),f.connection)+select('measurement-operation','Operation',['accounts','balances','transactions','consent'].map(op=>[op,op[0].toUpperCase()+op.slice(1)]),f.operation)+button('Reset filters','reset-measurements','quiet')+'</div>'+section('responses','Response measurements by connection',rows.length+' measurements',table)+section('imports','Imported measurement reports',imported.length+' reports',imported.length?runTable(imported):empty('No imported reports match','Import timestamped response samples or change the filters.'));
}

function reports(){const saved=state.workspace.savedReports||[];const runs=state.workspace.runs.filter(r=>r.status==='completed');return head('ACTIONABLE OUTPUTS','Reports','')+savedReportTable(saved)+availabilityPanel()+`<div class="grid two"><div class="card report-card">${icon('reports')}<h2>Incompatibility report</h2><p>Expected vs observed, selected rule, source locator, impact, remediation guidance and evidence mode. Platform checks stay separate from bank findings.</p><div class="chip-list"><span class="chip">Source-linked</span><span class="chip">Printable HTML / PDF</span><span class="chip">JSON export</span></div></div><div class="card report-card">${icon('monitor')}<h2>Quality report</h2><p>Per-operation counts, failure categories, p50 and p95. Small samples and missing measurements remain visible. Thresholds are not configured.</p><div class="chip-list"><span class="chip">Raw sample CSV</span><span class="chip">Measurement method</span><span class="chip">Observation coverage</span></div></div></div><div class="card space"><div class="card-head"><h2>Available report bundles</h2></div>${runs.length?`<div class="table-wrap"><table><thead><tr><th>Run</th><th>Evidence mode</th><th>Reports</th></tr></thead><tbody>${runs.map(r=>`<tr><td><b>${e(r.name)}</b><small>${date(r.finishedAt)}</small></td><td>${badge(r.evidenceMode)}</td><td><div class="buttons">${exportLink(r.id,'incompatibility','Findings')}${exportLink(r.id,'quality','Quality')}${exportLink(r.id,'json','JSON')}${canRun()?exportLink(r.id,'csv','CSV'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No reports available','Complete an audit to generate findings and quality reports.',canRun()?button('Run bank API audit','new-run','primary'):'')}</div>`}
function savedReportLink(report,label='Open full report'){return '<a class="btn small primary" href="/api/reports/'+e(report.id)+'/html" target="_blank" rel="noopener">'+icon('reports')+label+'</a>'}
function savedReportTable(reports){return '<div class="card saved-reports"><div class="card-head"><div><h2>Saved full reports</h2><p>Complete audit results, impact, and remediation in one saved document. Each version is preserved.</p></div>'+button('Refresh','refresh','small')+'</div>'+(reports.length?'<div class="table-wrap saved-reports-scroll"><table><thead><tr><th>Audit</th><th>Version</th><th>Saved</th><th>Report</th></tr></thead><tbody>'+reports.map(r=>'<tr><td><b>'+e(r.runName)+'</b><small>'+e(r.runId)+'</small></td><td>'+badge('v'+r.version)+'<small>'+e(r.reason)+'</small></td><td>'+date(r.createdAt)+'</td><td><div class="buttons">'+savedReportLink(r)+'<a class="btn small" href="/api/reports/'+e(r.id)+'" target="_blank" rel="noopener">Report JSON</a></div></td></tr>').join('')+'</tbody></table></div>':empty('No saved reports yet','Full reports are saved automatically when audits complete. Reports for older completed audits are prepared in the background.'))+'</div>'}
async function reportHistory(runId){const result=await api('/api/runs/'+runId+'/reports');modal('Saved report versions',savedReportTable(result.reports)+(canRun()?'<div class="buttons space">'+(result.reports[0]?button('Prepare report analysis','generate-report-explanation','','data-id="'+e(result.reports[0].id)+'"'):'')+button('Save new report version','new-report-version','','data-id="'+e(runId)+'"')+'</div><p class="footnote">A new version preserves the existing reports. It uses the retained audit results; it does not run bank requests.</p>':''))}
function showReportExplanationJob(job){modal('Report analysis','<p>'+e(job.status==='completed'?'A new report version has been saved. AI analysis is included when failures need explanation; passing and review-only results use a concise evidence-based summary.':job.status==='failed'?'The explanation could not be saved. The original report is unchanged. Retry from its version history.':'The report analysis is being prepared from the saved facts. You can close this window and return to report history.')+'</p><p class="footnote">AI is advisory. Recorded evidence, measurements and verdicts remain unchanged.</p><div class="buttons space">'+(job.reportId?savedReportLink({id:job.reportId},'Open report with explanations'):button('Refresh status','refresh-report-explanation','','data-id="'+e(job.id)+'"'))+'</div>')}
function newReportVersion(runId){modal('Save a new report version','<p>This creates a new saved document from the retained audit results. Earlier versions remain unchanged.</p><div class="field"><label for="report-reason">Reason for the new version</label><textarea id="report-reason" minlength="12" maxlength="300" placeholder="Describe why this report is being regenerated."></textarea></div><div id="report-version-error" class="error" role="alert"></div>'+button('Save report version','save-report-version','primary','data-id="'+e(runId)+'" data-request-id="'+crypto.randomUUID()+'"'))}

const exportLink=(id,type,label)=>`<a class="btn small" href="/api/runs/${e(id)}/export/${type}" target="_blank" rel="noopener">${icon('download')}${label}</a>`;
function filterRules(query){const needle=String(query||'').trim().toLowerCase();let visible=0;document.querySelectorAll('[data-rule-search]').forEach(row=>{row.hidden=!row.dataset.ruleSearch.includes(needle);if(!row.hidden)visible++;});const count=document.querySelector('#rule-search-count');if(count)count.textContent=visible?visible+' matching requirement'+(visible===1?'':'s'):'No requirements match. Try another name or identifier.';}
function standards(){const w=state.workspace;
 const summary=canReview()?`<div class="grid three space">${metric('Rules awaiting review',w.rules.filter(r=>r.status==='draft').length,'Review the source before activation','standards',false,'#standards-rules')}${metric('Approved rules',w.rules.filter(r=>r.status==='approved').length,'Approved checks are available to matching audits','check',false,'#standards-rules')}${metric('Reference documents',w.sources.length,'Read the original standards','reports',false,'#standards-sources')}</div>`:'';
 return head('','Standards & rules','Review the requirements that apply to each bank API.',canReview()?button(icon('plus')+' Compare source snapshot','source-update'):'')+summary+
 `<details class="card pad space legal-details"><summary>Which standards apply?</summary><p>The uploaded index points payment-account AIS to XS2A 0.8.RC3. Newer AIS and consent rules are not automatically applied to payment accounts.</p><div class="grid three space">${w.profiles.map(p=>`<div class="source-card"><h3>${e(p.name)}</h3>${badge(p.status)}<p>${e(p.note)}</p></div>`).join('')}</div></details>
 <div class="card pad space rule-search-field"><label for="rule-search">Search requirements</label><input id="rule-search" type="search" placeholder="Search by name or identifier, e.g. currency or AIS-CURRENCY" autocomplete="off"><p id="rule-search-count" class="smalltext" role="status" aria-live="polite">${w.rules.length} requirements</p></div><div id="standards-rules" tabindex="-1" class="card space"><div class="card-head"><div><h2>Requirements</h2><p>Open a requirement for its exact wording, source and scope. Draft rules do not run until approved.</p></div><span class="subtle">${w.rules.filter(r=>r.status==='approved').length} approved · ${w.rules.filter(r=>r.status==='draft').length} draft</span></div>
 ${w.rules.map(r=>`<article class="readable-rule" data-rule-search="${e((r.title+' '+r.id).toLowerCase())}"><div class="rule-heading"><h3>${e(r.title)}</h3>${badge(r.status)}</div><details class="legal-details"><summary>Source, applicability & review details</summary><dl class="rule-facts"><dt>Rule identifier</dt><dd>${e(r.id)}</dd><dt>Standard / profile</dt><dd>${e(profileLabel(r.profile))} (${e(r.profile)})</dd><dt>Source document</dt><dd>${e(r.source||r.sourceFile||'See original source below')}</dd><dt>Section</dt><dd>§${e(r.section)}</dd><dt>Exact source wording</dt><dd><blockquote>${e(r.quote||r.assertion||'Open the review to inspect the complete source clause.')}</blockquote></dd><dt>Applicability & review notes</dt><dd>${e(r.reviewNote||'Review the full source and its conditions before approval.')}</dd>${r.bankApplicability?`<dt>Applies to</dt><dd>${e(r.bankApplicability.join(', '))}</dd>`:''}<dt>Guidance</dt><dd>${e(r.fix||'Inspect the original requirement and the observable assertion.')}</dd><dt>Source fingerprint</dt><dd class="mono">${e(r.sourceHash||'Available in source review')}</dd></dl>${r.references?`<div class="source-reference-links">${r.references.map(ref=>`<a class="btn small" href="${e(ref.url)}" target="_blank" rel="noopener">${e(ref.label)}</a>`).join('')}</div>`:''}<a class="btn small" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(r.source)}">Read full source</a> ${button(canReview()?'Review requirement':'Inspect requirement','review-rule','small',`data-id="${e(r.id)}"`)}</details></article>`).join('')}</div>
 <details id="standards-sources" tabindex="-1" class="card pad space legal-details"><summary>Original reference documents (${w.sources.length})</summary><div class="grid two space">${w.sources.map(s=>`<div class="source-card"><h3>${e(s.name)}</h3><div class="mono">SHA-256 ${e(s.sha256)}</div><a class="btn small" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(s.file)}">Open extracted source ${icon('arrow')}</a></div>`).join('')}</div></details>${w.updates.length?`<div class="card space"><div class="card-head"><h2>Proposed source changes</h2></div>${w.updates.map(x=>`<div class="pad"><h3>${e(x.title)} ${badge(x.status)}</h3><p>${e(x.notice)}</p><p class="smalltext">${(x.added||[]).length} added lines · ${(x.removed||[]).length} removed lines · ${(x.affectedRules||[]).length} candidate rules affected</p><details class="space"><summary>Inspect text diff</summary><pre class="code light">${e((x.added||[]).map(x=>'+ '+x).join('\n')+'\n'+(x.removed||[]).map(x=>'- '+x).join('\n'))}</pre></details></div>`).join('')}</div>`:''}`}
function gates(){const w=state.workspace;return head('REGRESSIONS BEFORE PUBLICATION','Release gates','Evaluate a candidate against a completed run. Incomplete bank coverage holds publication.',canGate()?button('Compare specifications','spec-diff')+button(icon('plus')+' Evaluate candidate','new-gate','primary'):'')+notice('Release decision criteria','Failed checks reject a candidate. Missing bank evidence puts it on hold. Decisions apply to GeoBridge records and do not deploy or block external bank changes.')+`<div class="card space"><div class="card-head"><h2>Candidate decisions</h2></div>${w.gates.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Candidate</th><th>Decision</th><th>Reason</th><th>Time</th></tr></thead><tbody>${w.gates.map(g=>`<tr><td><b>${e(g.name)}</b><small>${e(String(g.runId||'').slice(0,8))}</small></td><td>${badge(g.decision)}</td><td>${e(g.reason)}</td><td>${date(g.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No release candidates evaluated','Complete an audit, then evaluate a candidate using its results. Bank approval requires bank evidence.')}</div>`}
function detail(){const r=state.run;if(!r)return empty('Loading run','Fetching persisted evidence…');const counts=resultCounts(r);return head('PERSISTED AUDIT EVIDENCE',e(r.name),`${e(profileLabel(r.profile))} · Created ${date(r.createdAt)}`,`<div class="buttons">${button(state.run.kind==='platform'?'← System diagnostics':'← Audit history',state.run.kind==='platform'?'nav-diagnostics':'nav-audit')}${canRun()?button('Retest','retest','primary',`data-id="${r.id}"`):''}</div>`)+`<div class="card"><div class="result-banner"><div><h2>${badge(r.status)} <span class="subtle">${e(r.id)}</span></h2><p>${e(r.evidenceMode||r.kind)} · ${r.finishedAt?'Finished '+date(r.finishedAt):'Waiting for worker result'}</p></div>${['queued','running'].includes(r.status)&&canRun()?button('Stop run','stop-run','danger',`data-id="${r.id}"`):''}</div>${['queued','running'].includes(r.status)?'<div class="loading-line"></div>':''}</div>${r.error?`<div class="notice amber space">${e(r.error)}</div>`:''}<div class="mini-stat">${summaryVerdictOrder.map(k=>`<button type="button" class="verdict-summary ${k.toLowerCase()}" data-action="jump-verdict" data-verdict="${k}" ${!(counts[k]>0)?'disabled':''} aria-label="${counts[k]||0} ${e(verdictLabels[k])}; jump to findings"><b>${counts[k]||0}</b>${badge(k)}</button>`).join('')}</div>${notice('Result scope','Local platform checks validate GeoBridge controls. Imported fixtures and uploaded captures are not live bank tests. Passing selected checks is not overall compliance.')}<div class="tabs space"><button class="tab ${state.filter==='all'?'active':''}" data-filter="all">All checks</button>${['compatibility','reliability','latency','security'].map(l=>`<button class="tab ${state.filter===l?'active':''}" data-filter="${l}">${l[0].toUpperCase()+l.slice(1)}</button>`).join('')}<button class="tab ${state.filter==='metrics'?'active':''}" data-filter="metrics">Quality metrics</button></div>${state.filter==='metrics'?metricDetail(r):groupedFindings(r)}${r.status==='completed'?`<div class="buttons space">${exportLink(r.id,'full','Open saved full report')}${button('Report version history','report-history','',`data-id="${e(r.id)}"`)}${exportLink(r.id,'incompatibility','Incompatibility report')}${exportLink(r.id,'quality','Quality report')}${exportLink(r.id,'json','Run JSON')}${canRun()?exportLink(r.id,'csv','Sample CSV'):''}</div><div class="card pad space"><h3>Run metadata</h3><p class="mono">Ruleset ${e(r.rulesetHash)}<br>Evidence ${e(r.evidenceHash||'Local platform controls; no bank response')}<br>Build ${e(r.build)}</p><p class="footnote">${(r.limitations||[]).map(e).join('<br>')}</p></div>`:''}`}
function metricDetail(r){return `<div class="card"><div class="card-head"><div><h2>Per-operation quality</h2><p>Successful positive-request timings only. No regulatory threshold configured.</p></div></div>${r.metrics?.some(m=>m.attempts)?`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Operation</th><th>Attempts</th><th>Success</th><th>Errors</th><th>Timeouts</th><th>p50</th><th>p95</th></tr></thead><tbody>${r.metrics.map(m=>`<tr><td>${e(m.operation)}</td><td>${m.attempts}</td><td>${m.successRate===null?'—':(m.successRate*100).toFixed(1)+'%'}</td><td>${m.errors}</td><td>${m.timeouts}</td><td>${m.p50===null?'—':m.p50+' ms'}</td><td>${m.p95===null?'Insufficient samples':m.p95+' ms'}</td></tr>`).join('')}</tbody></table></div>`:empty('No bank latency measurements','Internal test execution duration is not bank response time. Import timestamped measurement samples or connect a bank adapter.')}</div>`}
function render(){if(!state.user)return login();if(!policy().pages.includes(state.page)&&!(state.page==='connection-detail'&&policy().pages.includes('connections')&&state.workspace.connections.some(c=>c.id===state.connectionId))&&!(state.page==='detail'&&state.run&&(state.run.kind==='platform'?state.user.role==='operator':policy().pages.includes('audit'))))state.page=policy().home;const views={overview,audit,connections,'connection-detail':connectionDetail,explorer,oversight,monitor:monitoring,reports,standards,gate:gates,detail,diagnostics};if(state.page==='activity'){shell(head('WHO · WHAT · WHEN','Activity log','Permission-scoped events recorded by the backend.')+'<div id="activity-list" class="card">'+empty('Loading events','Retrieving the audit trail…')+'</div>');loadEvents().catch(err=>showError(err.message));return}shell((views[state.page]||overview)())}
async function loadEvents(){const rows=await api('/api/events');const el=document.querySelector('#activity-list');if(el)el.innerHTML=rows.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Action</th><th>Actor</th><th>Target</th><th>When</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(r.action.replaceAll('_',' '))}</td><td>${e(r.actor)}</td><td class="mono">${e(r.target)}</td><td>${date(r.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('No visible events','Events appear as you use the workspace.')}

async function showRun(id){state.run=await api('/api/runs/'+id);state.page='detail';state.filter='all';state.menuOpen=false;render();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'})}
async function startRun(body){const r=await api(body.kind==='platform'?'/api/diagnostics':'/api/runs',{method:'POST',body});dialog.close();await refresh();await showRun(r.id)}
function newRun(){modal('Run bank API audit',`<p>Choose a bank connection. Readiness is checked before any audit is queued.</p><div class="field"><label for="run-connection">Bank connection</label><select id="run-connection"><option value="">Select a connection</option>${state.workspace.connections.filter(c=>state.user.role==='operator'||c.synthetic&&c.status==='mock_configured').map(c=>`<option value="${e(c.id)}">${e(c.name)}${c.synthetic?' (mock)':''}</option>`).join('')}</select></div><div id="bank-readiness" role="status" aria-live="polite"></div><div class="buttons space">${button('Run bank API audit','execute-run','primary')}</div>`)}
function reviewSaved(){modal('Review saved API responses',`<p>Review stored responses against selected rules. This does not send requests to a bank.</p><div class="field"><label for="run-pack">Saved response set</label><select id="run-pack"><option value="">Select saved responses</option>${state.workspace.packs.map(p=>`<option value="${e(p.id)}">${e(p.name)} · ${e(p.mode)}</option>`).join('')}</select></div><div class="buttons">${button('Review selected responses','execute-saved','primary')}${canConfigure()?button('Import responses','import-evidence'):''}</div>`)}
async function runBankAudit(connectionId,control){
 if(!connectionId)throw Error('Select a bank connection.');
 if(control)control.disabled=true;
 try{const readiness=await api('/api/connections/'+encodeURIComponent(connectionId)+'/readiness');
 if(!readiness.ready){const message=readiness.reasons.map(r=>r.message).join(' '),out=document.querySelector('#bank-readiness');if(dialog.open&&out){out.innerHTML=notice('Connection is not ready',readiness.reasons.map(r=>e(r.message)).join('<br>'),true)}else toast(message);return}
 await startRun({kind:'bank',connectionId});
 }finally{if(control)control.disabled=false}
}
async function signOut(){
 if(state.busy)return;state.busy=true;
 const screen=document.createElement('div');screen.className='session-transition';screen.setAttribute('role','status');screen.innerHTML='<div><span class="login-dots" aria-hidden="true"><i></i><i></i><i></i></span><p>Signing out…</p></div>';document.body.appendChild(screen);
 try{await Promise.all([api('/api/logout',{method:'POST'}),new Promise(resolve=>setTimeout(resolve,450))]);clearSession();login();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'})}
 catch(err){showError(err.message)}finally{screen.remove();state.busy=false}
}

function registerSandbox(){
 const field=(key,label,options={})=>{const {type='text',required=true,placeholder='',value='',hint='',attrs='',select=''}=options;return '<div class="field"><label for="sandbox-'+key+'">'+label+(required?' <span class="required-star" aria-hidden="true">*</span>':'')+'</label>'+(select?'<select id="sandbox-'+key+'" name="'+key+'" '+(required?'required':'')+'>'+select+'</select>':'<input id="sandbox-'+key+'" name="'+key+'" type="'+type+'" '+(required?'required':'')+' placeholder="'+e(placeholder)+'" value="'+e(value)+'" '+attrs+'>')+(hint?'<small id="sandbox-'+key+'-hint">'+hint+'</small>':'')+'<p class="field-error" id="sandbox-'+key+'-error"></p></div>'};
 const profiles=state.workspace.profiles.filter(p=>p.id!=='platform');
 modal('Register sandbox connection',
 '<form id="sandbox-form" novalidate><ol class="registration-steps" aria-label="Registration progress"><li data-step-label="1" aria-current="step"><b>1</b> Bank & API</li><li data-step-label="2"><b>2</b> Authentication & access</li></ol><p class="registration-intro">Fields marked <span class="required-star">*</span> are required. Registration saves connection settings; it does not activate bank access.</p><div id="sandbox-errors" class="registration-errors" role="alert" tabindex="-1" hidden></div>'+
 '<fieldset data-registration-step="1"><legend>Bank and API details</legend><div class="registration-grid">'+
 field('name','Connection name',{placeholder:'Bank A — developer sandbox',attrs:'minlength="3" maxlength="100"'})+
 field('bankName','Bank / institution name',{placeholder:'Registered institution name',attrs:'minlength="2" maxlength="120"'})+
 field('country','Country code',{placeholder:'GE',value:'GE',attrs:'pattern="[A-Za-z]{2}" minlength="2" maxlength="2"',hint:'Two-letter country code.'})+
 field('contactEmail','Technical contact email',{type:'email',placeholder:'api-team@example.com',attrs:'maxlength="160"'})+
 field('profile','API profile',{select:'<option value="">Select the applicable profile</option>'+profiles.map(p=>'<option value="'+e(p.id)+'">'+e(p.name)+'</option>').join('')})+
 '<div class="field"><label>Environment</label><div class="registration-environment">Sandbox</div><small>For sandbox API connections only.</small></div>'+
 field('baseUrl','Sandbox API base URL',{type:'url',placeholder:'https://sandbox.bank.example/api',hint:'HTTPS only. This host must be approved by the Operator before registration.'})+
 field('documentationUrl','API documentation URL',{type:'url',placeholder:'https://developer.bank.example/docs'})+
 '</div></fieldset><fieldset data-registration-step="2" hidden><legend>Authentication and access</legend><div class="registration-grid">'+
 field('authMethod','Authentication method',{select:'<option value="">Select authentication</option><option value="oauth2">OAuth 2.0 — authorization code</option><option value="oauth2_mtls">OAuth 2.0 + mutual TLS</option><option value="mtls">Mutual TLS</option><option value="api_key">API key</option>'})+
 field('credentialReference','Credential store reference',{placeholder:'sandbox/bank-a/credentials',attrs:'data-validation="reference" maxlength="120"',hint:'Reference to server-managed credentials. Do not paste a secret or token.'})+
 '<div class="registration-conditional full" data-auth-fields="oauth2 oauth2_mtls" hidden><div class="registration-grid">'+
 field('clientId','OAuth client ID',{placeholder:'Client ID issued by the bank',attrs:'maxlength="160"'})+
 field('scopes','Requested OAuth scopes',{placeholder:'accounts balances transactions',attrs:'maxlength="300" data-validation="scopes"',hint:'Space-separated scopes approved by the sandbox.'})+
 field('authorizationUrl','Authorization endpoint',{type:'url',placeholder:'https://sandbox.bank.example/oauth/authorize'})+
 field('tokenUrl','Token endpoint',{type:'url',placeholder:'https://sandbox.bank.example/oauth/token'})+
 field('redirectUri','Registered redirect URI',{type:'url',placeholder:'https://your-app.example/oauth/callback',hint:'Must match the URI registered with the bank. Saving it here does not implement an OAuth callback.'})+
 '</div></div><div class="registration-conditional full" data-auth-fields="mtls oauth2_mtls" hidden>'+field('certificateReference','Client certificate reference',{placeholder:'sandbox/bank-a/client-certificate',attrs:'data-validation="reference" maxlength="120"',hint:'Reference to the certificate and private key managed on the server.'})+'</div><div class="registration-conditional full" data-auth-fields="api_key" hidden>'+field('apiKeyHeader','API key header name',{placeholder:'X-API-Key',attrs:'maxlength="80" data-validation="header"',hint:'Header name only. The value belongs in the credential store.'})+'</div>'+
 field('timeoutMs','Request timeout (ms)',{type:'number',value:'5000',attrs:'min="1000" max="30000" step="1"'})+
 '<div class="field"><label>Requested operations <span class="required-star" aria-hidden="true">*</span></label><div class="operation-options" role="group" aria-label="Requested operations" aria-describedby="sandbox-operations-error">'+['accounts','balances','transactions'].map(op=>'<label><input type="checkbox" name="operations" value="'+op+'"> '+op[0].toUpperCase()+op.slice(1)+'</label>').join('')+'</div><p class="field-error" id="sandbox-operations-error"></p></div>'+
 '</div><p class="registration-note">Credentials, certificate references, and consent must be configured and verified by the Operator before bank API audits can run.</p></fieldset><div class="registration-actions"><button type="button" class="btn" id="sandbox-back" hidden>Back</button><span id="sandbox-step-count">Step 1 of 2</span><button type="submit" class="btn primary" id="sandbox-next">Next '+icon('arrow')+'</button></div></form>');
 const form=document.querySelector('#sandbox-form'),summary=document.querySelector('#sandbox-errors'),next=document.querySelector('#sandbox-next'),back=document.querySelector('#sandbox-back');let step=1,saving=false;
 const controls=()=>Array.from(form.querySelectorAll('input,select'));
 const showError=(key,message)=>{const control=form.elements.namedItem(key),out=document.querySelector('#sandbox-'+key+'-error');if(out)out.textContent=message;if(control?.setAttribute){control.setAttribute('aria-invalid',String(!!message));control.setAttribute('aria-describedby','sandbox-'+key+'-error'+(document.querySelector('#sandbox-'+key+'-hint')?' sandbox-'+key+'-hint':''))}};
 const switchStep=number=>{step=number;form.querySelectorAll('[data-registration-step]').forEach(el=>el.hidden=Number(el.dataset.registrationStep)!==step);form.querySelectorAll('[data-step-label]').forEach(el=>{if(Number(el.dataset.stepLabel)===step)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});back.hidden=step===1;next.innerHTML=step===1?'Next '+icon('arrow'):'Register sandbox';document.querySelector('#sandbox-step-count').textContent='Step '+step+' of 2';summary.hidden=true;dialog.scrollTop=0;const first=form.querySelector('[data-registration-step="'+step+'"] input:not(:disabled),[data-registration-step="'+step+'"] select');first?.focus({preventScroll:true});};
 const authFields=()=>{const method=form.elements.authMethod.value;form.querySelectorAll('[data-auth-fields]').forEach(group=>{const active=group.dataset.authFields.split(' ').includes(method);group.hidden=!active;group.querySelectorAll('input,select').forEach(control=>{control.disabled=!active;if(!active)showError(control.name,'')})})};
 const validate=number=>{let valid=true;const group=form.querySelector('[data-registration-step="'+number+'"]');group.querySelectorAll('input,select').forEach(control=>{if(control.disabled||control.type==='checkbox')return;control.setCustomValidity('');const patterns={reference:/^[a-zA-Z0-9][a-zA-Z0-9._:/-]{1,119}$/,scopes:/^[a-zA-Z0-9._:/-]+(?: +[a-zA-Z0-9._:/-]+)*$/,header:/^[A-Za-z][A-Za-z0-9-]*$/};if(control.value&&patterns[control.dataset.validation]&&!patterns[control.dataset.validation].test(control.value))control.setCustomValidity(control.dataset.validation==='scopes'?'Use space-separated scope names.':control.dataset.validation==='header'?'Enter a header name such as X-API-Key.':'Use a credential store reference, not a secret or token.');if(control.type==='url'&&control.value.trim()){try{const url=new URL(control.value.trim());if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||(url.port&&url.port!=='443')||url.hostname==='localhost'||!url.hostname.includes('.')||/^[\d.]+$/.test(url.hostname)||url.hostname.startsWith('['))throw Error()}catch{control.setCustomValidity('Enter a public HTTPS URL without credentials, query parameters, or fragments.')}}const message=control.checkValidity()?'':control.validationMessage;showError(control.name,message);if(message)valid=false});if(number===2){const checked=form.querySelectorAll('input[name="operations"]:checked').length;showError('operations',checked?'':'Select at least one operation.');if(!checked)valid=false}return valid};
 const reportInvalid=()=>{summary.textContent='Complete the required fields and correct the highlighted values.';summary.hidden=false;form.querySelector('[data-registration-step="'+step+'"] [aria-invalid="true"]')?.focus()};
 controls().forEach(control=>{const ids=['sandbox-'+control.name+'-error'];if(document.querySelector('#sandbox-'+control.name+'-hint'))ids.push('sandbox-'+control.name+'-hint');if(control.type!=='checkbox')control.setAttribute('aria-describedby',ids.join(' '))});
 form.addEventListener('input',ev=>{if(ev.target.setCustomValidity)ev.target.setCustomValidity('');showError(ev.target.name,'')});
 form.addEventListener('change',ev=>{if(ev.target.name==='authMethod')authFields();if(ev.target.name==='operations')showError('operations','')});
 back.onclick=()=>{if(!saving)switchStep(1)};authFields();
 form.onsubmit=async ev=>{ev.preventDefault();if(saving)return;if(!validate(step)){reportInvalid();return}if(step===1){switchStep(2);return}if(!validate(1)){switchStep(1);reportInvalid();return}
 const payload=Object.fromEntries(new FormData(form));payload.operations=Array.from(form.querySelectorAll('input[name="operations"]:checked'),el=>el.value);payload.timeoutMs=Number(payload.timeoutMs);
 saving=true;next.disabled=true;back.disabled=true;next.textContent='Registering…';summary.hidden=true;
 try{await api('/api/connections',{method:'POST',body:payload});dialog.close();await refresh();toast('Sandbox settings saved. Adapter, credentials, and consent still require verification.')}catch(err){if(!form.isConnected)return;const entries=Object.entries(err.fieldErrors||{});const firstKey=entries[0]?.[0];if(firstKey){const control=form.elements.namedItem(firstKey);if(control?.closest('[data-registration-step]'))switchStep(Number(control.closest('[data-registration-step]').dataset.registrationStep));entries.forEach(([key,message])=>showError(key,message))}summary.textContent=err.message;summary.hidden=false;summary.focus()}finally{saving=false;next.disabled=false;back.disabled=false;next.textContent=step===1?'Next':'Register sandbox'}
 };
}

function importEvidence(){modal('Import synthetic response evidence',`<p>Use the documented JSON format. Credentials and common identifiers are redacted before persistence.</p><div class="field"><label for="evidence-file">JSON file</label><input type="file" accept=".json,application/json" id="evidence-file"></div><div class="field"><label for="evidence-json">Evidence pack JSON</label><textarea id="evidence-json" style="min-height:230px" placeholder="Paste JSON or load the fictional example"></textarea></div><label class="check"><input type="checkbox" id="synthetic-confirm">I confirm all data is synthetic and the evidence mode accurately identifies fixtures or sandbox captures.</label><div class="buttons">${button('Load fictional example','load-example')}${button('Import evidence','save-evidence','primary')}</div><p class="footnote">The example has no timing samples. We do not manufacture performance results.</p>`)}
async function findingDetail(id){const r=state.run,f=r.results.find(x=>x.id===id);let raw='';if(canConfigure()&&r.packId&&f.observationIndex!==undefined){const p=await api('/api/packs/'+r.packId);raw=JSON.stringify(p.observations[f.observationIndex],null,2)}modal('Finding details',`<h3>${e(f.title)} ${badge(f.verdict)}</h3><p class="mono">${e(f.ruleId||f.id)} · ${e(f.basis||'Selected rule')} · ${e(r.evidenceMode)}</p><div class="detail-grid space"><div class="detail-block"><label>Expected</label>${e(f.expected)}</div><div class="detail-block"><label>Observed</label>${e(f.observed)}</div><div class="detail-block full"><label>Suggested action</label>${e(f.fix||'Review the recorded control assertions. Retest after any relevant implementation change.')}</div></div>${f.quote?`<div class="quote">${e(f.quote)}</div><p class="smalltext">${e(f.source)} · §${e(f.section)} · ${e(f.reviewNote)}</p>`:''}${raw?`<details class="space"><summary>Original redacted evidence</summary><pre class="code">${e(raw)}</pre></details>`:''}${f.verdict==='BLOCKED'?'':`<div class="divider"></div><h3>Explanation assistance</h3><p class="smalltext">Verdicts stay deterministic. AI advice is bounded and may be incorrect.</p><div class="buttons space">${button('Explain in English','explain','small',`data-id="${e(f.id)}" data-language="en"`)}${button('განმარტება ქართულად','explain','small',`data-id="${e(f.id)}" data-language="ka"`)}</div><div id="explanation-result"></div>`}<p class="footnote">Reproduce: select this run’s evidence pack and profile, then Retest. Raw sample CSV is available from the run.</p>`)}
async function reviewRule(id){const r=state.workspace.rules.find(x=>x.id===id);modal('Review source and applicability',`<h3>${e(r.id)} · ${e(r.title)} ${badge(r.status)}</h3><p class="smalltext">${e(r.profile)} · ${e(r.source)} · §${e(r.section)}</p>${r.bankApplicability?`<p class="smalltext">Applies to: ${e(r.bankApplicability.join(', '))} · Legacy payment-account AIS only</p>`:''}<div class="quote">${e(r.quote)}</div><p>${e(r.fix)}</p>${r.references?`<div class="source-reference-links">${r.references.map(ref=>`<a class="btn small" href="${e(ref.url)}" target="_blank" rel="noopener">${e(ref.label)} ${icon('arrow')}</a>`).join('')}</div>`:''}<p class="footnote">${e(r.reviewNote)}<br>Source hash: ${e(r.sourceHash)}</p><a class="btn small space" target="_blank" rel="noopener" href="/api/sources?file=${encodeURIComponent(r.source)}">Read full source ${icon('arrow')}</a>${canReview()?`<div class="field"><label for="review-note">Reviewer applicability note</label><textarea id="review-note" placeholder="Record the account category, selected service, mandatory/conditional nature and observed assertion being approved."></textarea></div><label class="check"><input type="checkbox" id="review-confirm">I reviewed the source and conditions. This approval covers only the implemented observable assertion, not full legal compliance.</label><div class="buttons">${button('Approve rule','approve-rule','primary',`data-id="${r.id}"`)}${button('Keep as draft','draft-rule','',`data-id="${r.id}"`)}</div>`:notice('Reviewer access required','Use the NBG Reviewer account to approve executable rules.')}`)}
document.addEventListener('input',ev=>{if(ev.target.id==='rule-search'){filterRules(ev.target.value);return;}if(ev.target.dataset?.historyDate)ev.target.setCustomValidity('');});
document.addEventListener('change',async ev=>{if(ev.target.dataset?.historyDate){const value=parseFilterDate(ev.target.value);if(value===null){ev.target.setCustomValidity('Use DD/MM/YYYY and enter a valid date.');ev.target.reportValidity();return;}ev.target.setCustomValidity('');state.historyFilters={...(state.historyFilters||{}),[ev.target.dataset.historyDate]:value};const id=ev.target.id;render();document.querySelector('#'+id)?.focus();return;}if(ev.target.dataset?.historyFilter){state.historyFilters={...(state.historyFilters||{}),[ev.target.dataset.historyFilter]:ev.target.value};render();document.querySelector('#'+ev.target.id)?.focus();return}if(ev.target.id==='measurement-connection'||ev.target.id==='measurement-operation'){state.measurementFilters={...(state.measurementFilters||{connection:'',operation:''}),[ev.target.id==='measurement-connection'?'connection':'operation']:ev.target.value};render();document.querySelector('#'+ev.target.id)?.focus();return}if(ev.target.id==='mobile-nav'){navigate(ev.target.value)}if(ev.target.id==='mapping-operation'){document.querySelector('#mapping-json').value=JSON.stringify(mappingSamples[ev.target.value],null,2)}if(ev.target.id==='evidence-file'){const f=ev.target.files[0];if(f){if(f.size>2e6)return toast('File exceeds 2 MB');document.querySelector('#evidence-json').value=await f.text()}}});
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-nav],[data-run],[data-filter],[data-finding]');if(!el)return;try{
 if(el.dataset.nav){return navigate(el.dataset.nav)}if(el.dataset.run)return await showRun(el.dataset.run);if(el.dataset.filter){state.filter=el.dataset.filter;return render()}if(el.dataset.finding)return await findingDetail(el.dataset.finding);
 const a=el.dataset.action;if(a==='generate-report-explanation'){el.disabled=true;const id=el.dataset.id;try{const job=await api('/api/reports/'+id+'/explanation',{method:'POST',body:{}});return showReportExplanationJob(job)}catch(error){toast(error.message)}finally{el.disabled=false}return}if(a==='refresh-report-explanation'){el.disabled=true;try{return showReportExplanationJob(await api('/api/report-explanations/'+el.dataset.id))}finally{el.disabled=false}}if(a==='report-history')return await reportHistory(el.dataset.id);if(a==='new-report-version')return newReportVersion(el.dataset.id);if(a==='save-report-version'){const reason=document.querySelector('#report-reason').value.trim(),out=document.querySelector('#report-version-error');if(reason.length<12||reason.length>300){out.textContent='Enter a reason between 12 and 300 characters.';return}el.disabled=true;try{await api('/api/runs/'+el.dataset.id+'/reports',{method:'POST',body:{reason,requestId:el.dataset.requestId}});await refresh();return await reportHistory(el.dataset.id)}catch(error){if(out.isConnected)out.textContent=error.message;else toast(error.message)}finally{el.disabled=false}return}if(a==='jump-section'){const section=document.getElementById(el.dataset.section);if(section){if(section.tagName==='DETAILS')section.open=true;section.scrollIntoView({behavior:'smooth',block:'start'});section.focus({preventScroll:true});}return;}if(a==='history-calendar'){const picker=document.querySelector('#history-'+el.dataset.key+'-picker');if(picker?.showPicker)picker.showPicker();else picker?.click();return;}if(a==='open-connection'){state.connectionId=el.dataset.id;state.page='connection-detail';state.menuOpen=false;render();globalThis.window?.scrollTo({top:0,left:0,behavior:'instant'});return;}if(dialog.open){const message=document.querySelector('#dialog-message');if(message)message.hidden=true;}if(a==='scroll-top'){smoothTop();return}if(a==='jump-verdict'){jumpVerdict(el.dataset.verdict);return}if(a==='reset-history'){state.historyFilters={bank:'',from:'',to:'',group:'none'};render();return}if(a==='reset-measurements'){state.measurementFilters={connection:'',operation:''};render();return}if(a==='toggle-menu'||a==='close-menu'){setMenu(a==='toggle-menu'&&!state.menuOpen);return}if(a.startsWith('nav-')){return navigate(a.slice(4))}if(a==='close')return dialog.close();if(a==='refresh')return await refresh();if(a==='logout')return await signOut();
 if(a==='compare-runs'){const rs=state.workspace.runs.filter(r=>r.status==='completed');const opts=selected=>rs.map((r,i)=>`<option value="${e(r.id)}" ${i===selected?'selected':''}>${e(r.name)} · ${date(r.finishedAt||r.createdAt)}</option>`).join('');return modal('Compare audits',`<p>Compare two completed audits for the same bank, profile and evidence type.</p><div class="comparison-pickers"><div class="field"><label for="compare-before">Earlier audit</label><select id="compare-before">${opts(rs.length>1?1:0)}</select></div><div class="field"><label for="compare-after">Later audit</label><select id="compare-after">${opts(0)}</select></div></div>${button('Compare audits','compare-execute','primary')}<div id="compare-result" aria-live="polite"></div>`)}
 if(a==='compare-execute'){const before=document.querySelector('#compare-before').value,after=document.querySelector('#compare-after').value;if(!before||!after)throw Error('Choose two completed audits.');if(before===after)throw Error('Choose two different audits to compare.');el.disabled=true;const original=el.textContent;el.textContent='Comparing…';try{const x=await api('/api/compare',{method:'POST',body:{before,after}});document.querySelector('#compare-result').innerHTML=comparisonResult(x);document.querySelector('#comparison-heading')?.focus({preventScroll:true});}finally{el.disabled=false;el.textContent=original;}return}

 if(a==='spec-diff')return modal('Compare candidate OpenAPI specifications',`<p>Structural diff only. No external deployment or automatic normative inference.</p><div class="field"><label for="spec-before">Baseline OpenAPI JSON</label><textarea id="spec-before"></textarea></div><div class="field"><label for="spec-after">Candidate OpenAPI JSON</label><textarea id="spec-after"></textarea></div>${button('Compare endpoints','spec-diff-execute','primary')}<div id="spec-diff-result"></div>`);
 if(a==='spec-diff-execute'){const x=await api('/api/spec-diff',{method:'POST',body:{before:JSON.parse(document.querySelector('#spec-before').value),after:JSON.parse(document.querySelector('#spec-after').value)}});document.querySelector('#spec-diff-result').innerHTML='<pre class="code space">'+e(JSON.stringify(x,null,2))+'</pre>';return}

 if(a==='availability-refresh'){await refresh();return}
 if(a==='availability-config'){
  const t=(state.availability||[]).find(t=>t.id===el.dataset.id),r=t.report;
  return modal('Configure synthetic availability monitoring',`<p>Checks GET /api/health, not all bank operations. Monitoring continues while the backend is running, including during an outage.</p><label class="check"><input id="availability-enabled" type="checkbox" ${r.enabled?'checked':''}> Enable monitoring</label><div class="field"><label>Probe interval (seconds)</label><input id="availability-interval" type="number" min="5" max="3600" value="${r.intervalSeconds}"></div><div class="field"><label>Absolute deadline (seconds)</label><input id="availability-timeout" type="number" min="1" max="10" value="${r.timeoutSeconds}"></div>${button('Save','availability-save','primary',`data-id="${e(t.id)}"`)}`);
 }
 if(a==='availability-save'){await api('/api/availability/'+el.dataset.id+'/configure',{method:'POST',body:{enabled:document.querySelector('#availability-enabled').checked,intervalSeconds:Number(document.querySelector('#availability-interval').value),timeoutSeconds:Number(document.querySelector('#availability-timeout').value)}});dialog.close();await refresh();return}
 if(a==='availability-switch'){if(!confirm(el.dataset.online==='true'?'Restore synthetic API responses?':'Stop synthetic API responses? Monitoring will continue and record failures.'))return;el.disabled=true;try{await api('/api/availability/'+el.dataset.id+'/switch',{method:'POST',body:{online:el.dataset.online==='true'}});toast('Mock switch applied. Observed status changes after the next probe.');await refresh()}finally{el.disabled=false}return}
 if(a==='availability-probe'){await api('/api/availability/'+el.dataset.id+'/probe',{method:'POST',body:{}});await refresh();return}
 if(a==='availability-report'){
  const r=await api('/api/availability/'+el.dataset.id+'/report');
  return modal('Availability report · '+e(r.name),`<p>SYNTHETIC · ${e(r.probe)}</p><p>Window: ${date(r.window.from)} – ${date(r.window.to)}</p><p>Successful checks: ${pct(r.successfulChecksPercent)} (${r.successes}/${r.checks}) · Estimated uptime in covered intervals: ${pct(r.estimatedUptimePercent)} · Coverage: ${pct(r.coveragePercent)}</p><p>Estimated down: ${duration(r.estimatedDownMs)} · Unknown/unobserved: ${duration(r.unknownMs)}</p><h3>Detected incidents</h3>${r.incidents.length?'<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Detected</th><th>Last success</th><th>Recovered</th><th>Duration from detection</th></tr></thead><tbody>'+r.incidents.map(i=>'<tr><td>'+date(i.detectedAt)+'</td><td>'+date(i.lastSuccessfulAt)+'</td><td>'+(i.endedAt?date(i.endedAt):i.interrupted?'Observation interrupted':'No recovery observed')+'</td><td>'+(i.estimatedDurationMs===undefined?'Unknown/open':duration(i.estimatedDurationMs))+'</td></tr>').join('')+'</tbody></table></div>':'<p>No incidents observed in this window.</p>'}<h3>Recent probes</h3><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable results"><table><thead><tr><th>Time</th><th>Result</th><th>HTTP</th><th>Duration</th></tr></thead><tbody>${r.recentSamples.slice().reverse().map(p=>'<tr><td>'+date(p.at)+'</td><td>'+e(p.outcome)+'</td><td>'+e(p.httpStatus??'No response')+'</td><td>'+p.durationMs+' ms</td></tr>').join('')}</tbody></table></div><ul>${r.limitations.map(l=>'<li>'+e(l)+'</li>').join('')}</ul><div class="buttons"><a class="btn" href="/api/availability/${e(r.id)}/report?format=json" target="_blank" rel="noopener">Export JSON</a><a class="btn" href="/api/availability/${e(r.id)}/report?format=csv">Export CSV</a></div>`);
 }

 if(a==='gringott-consent'){
  el.disabled=true;try{const cid=document.querySelector('#gringott-connection').value;const x=await api('/bridge/v1/connections/'+cid+'/consents',{method:'POST',body:{}});state.gringott={connection:cid,...x};render();toast('Synthetic consent granted. Tokens stay on the server.')}finally{el.disabled=false}return;
 }
 if(a==='gringott-revoke'){
  const s=state.gringott;try{await api('/bridge/v1/connections/'+s.connection+'/consents/'+s.consentId,{method:'DELETE'});}finally{state.gringott=null;render()}return;
 }
 if(a==='gringott-request'){
  const s=state.gringott;if(!s)throw Error('Grant simulated consent first');
  const operation=document.querySelector('#gringott-operation').value,account=document.querySelector('#gringott-account').value;
  const route='/bridge/v1/connections/'+s.connection+'/accounts'+(operation==='accounts'?'':'/'+encodeURIComponent(account)+'/'+operation);
  const out=document.querySelector('#gringott-response');el.disabled=true;
  try{const x=await api(route,{headers:{'Consent-ID':s.consentId}});out.textContent=JSON.stringify(x,null,2)}catch(err){out.textContent=err.message}finally{el.disabled=false}return;
 }
 if(a==='new-run')return newRun();if(a==='run-platform')return await startRun({kind:'platform'});if(a==='review-saved')return reviewSaved();if(a==='execute-saved'){const packId=document.querySelector('#run-pack').value;if(!packId)throw Error('Select saved responses.');el.disabled=true;try{return await startRun({kind:'evidence',packId})}finally{el.disabled=false}}if(a==='execute-run')return await runBankAudit(document.querySelector('#run-connection').value,el);
 if(a==='run-spec')return await startRun({kind:'spec',connectionId:el.dataset.id});if(a==='readiness')return await runBankAudit(el.dataset.id,el);if(a==='retest'){const r=state.run;if(r.kind==='bank')return await runBankAudit(r.connectionId,el);return await startRun({kind:r.kind,packId:r.packId,connectionId:r.connectionId})}
 if(a==='stop-run'){await api('/api/runs/'+el.dataset.id+'/stop',{method:'POST'});await showRun(el.dataset.id);return}
 if(a==='import-evidence')return importEvidence();if(a==='load-example'){document.querySelector('#evidence-json').value=JSON.stringify(await api('/api/example'),null,2);return}
 if(a==='save-evidence'){if(!document.querySelector('#synthetic-confirm').checked)throw Error('Confirm synthetic data first');const b=JSON.parse(document.querySelector('#evidence-json').value);const result=await api('/api/packs',{method:'POST',body:b});dialog.close();await refresh();toast('Responses imported. Select them in Review saved API responses.');return}
 if(a==='normalize'){const b=JSON.parse(document.querySelector('#mapping-json').value);const result=await api('/api/normalize',{method:'POST',body:{synthetic:true,operation:document.querySelector('#mapping-operation').value,body:b}});document.querySelector('#mapping-result').innerHTML=badge('Validated','pass')+'<pre class="code space">'+e(JSON.stringify(result,null,2))+'</pre>';return}
 if(a==='mapping-fault'){const b=structuredClone(mappingSamples.balances);delete b.balances[0].balanceAmount.currency;document.querySelector('#mapping-operation').value='balances';document.querySelector('#mapping-json').value=JSON.stringify(b,null,2);return}
 if(a==='bridge-check'){try{const x=await api('/bridge/v1/connections/pending/accounts');document.querySelector('#bridge-result').innerHTML='<pre class="code">'+e(JSON.stringify(x,null,2))+'</pre>'}catch(err){document.querySelector('#bridge-result').innerHTML='<div class="notice amber space">'+e(err.message)+'</div>'}return}
 if(a==='new-connection')return registerSandbox();

 if(a==='upload-spec')return modal('Upload OpenAPI JSON',`<p>Remote references are not fetched. No secrets should be included.</p><div class="field"><label for="spec-json">OpenAPI 3 JSON</label><textarea id="spec-json" placeholder='{"openapi":"3.0.3","info":{},"paths":{}}'></textarea></div>${button('Save specification','save-spec','primary',`data-id="${el.dataset.id}"`)}`);
 if(a==='save-spec'){const x=await api('/api/connections/'+el.dataset.id+'/spec',{method:'POST',body:{spec:JSON.parse(document.querySelector('#spec-json').value)}});dialog.close();await refresh();toast(x.notice);if(x.runId)await showRun(x.runId);return}
 if(a==='review-rule')return await reviewRule(el.dataset.id);
 if(['approve-rule','draft-rule'].includes(a)){await api('/api/rules/'+el.dataset.id+'/review',{method:'POST',body:{approve:a==='approve-rule',confirm:document.querySelector('#review-confirm').checked,note:document.querySelector('#review-note').value}});dialog.close();await refresh();return toast('Rule review recorded')}
 if(a==='explain'){el.disabled=true;try{const x=await api('/api/runs/'+state.run.id+'/explain',{method:'POST',body:{findingId:el.dataset.id,language:el.dataset.language}});document.querySelector('#explanation-result').innerHTML=`<div class="detail-block space"><label>${e(x.mode.replaceAll('_',' '))}${x.cached?' · cached':''}</label><p>${e(x.summary)}</p><p style="margin-top:10px">${e(x.impact)}</p><p style="margin-top:10px">${e(x.fix)}</p><small>${e(x.reason||x.reviewStatus||'')} · ${date(x.generatedAt)}</small></div>`}finally{el.disabled=false}return}
 if(a==='new-schedule')return modal('Schedule an audit job',`<p>The local server must remain running. Uploaded evidence reviews are replays, not new bank measurements.</p><div class="field"><label for="schedule-kind">Job</label><select id="schedule-kind"><option value="evidence">Review imported evidence</option><option value="bank">Run mock bank API audit</option></select></div><div class="field"><label for="schedule-pack">Evidence pack</label><select id="schedule-pack"><option value="">Select</option>${state.workspace.packs.map(p=>`<option value="${p.id}">${e(p.name)}</option>`).join('')}</select></div><div class="field"><label for="schedule-connection">Connection</label><select id="schedule-connection">${state.workspace.connections.filter(c=>state.user.role==='operator'||c.synthetic&&c.status==='mock_configured').map(c=>`<option value="${c.id}">${e(c.name)}</option>`).join('')}</select></div><div class="field"><label for="schedule-minutes">Interval in minutes</label><input id="schedule-minutes" type="number" min="1" max="1440" value="60"></div>${button('Create schedule','save-schedule','primary')}`);
 if(a==='save-schedule'){await api('/api/schedules',{method:'POST',body:{kind:document.querySelector('#schedule-kind').value,packId:document.querySelector('#schedule-pack').value,connectionId:document.querySelector('#schedule-connection').value,minutes:Number(document.querySelector('#schedule-minutes').value)}});dialog.close();await refresh();return toast('Schedule created')}
 if(a==='delete-schedule'){await api('/api/schedules/'+el.dataset.id,{method:'DELETE'});return await refresh()}
 if(a==='new-gate')return modal('Evaluate a release candidate',`<p>This records a publication decision; it does not deploy or modify an external API.</p><div class="field"><label for="gate-name">Candidate name</label><input id="gate-name" placeholder="Adapter 0.1.0 candidate"></div><div class="field"><label for="gate-run">Completed evidence run</label><select id="gate-run"><option value="">Select a run</option>${state.workspace.runs.filter(r=>r.status==='completed').map(r=>`<option value="${r.id}">${e(r.name)} · ${date(r.finishedAt)}</option>`).join('')}</select></div>${button('Evaluate gate','save-gate','primary')}`);
 if(a==='save-gate'){const x=await api('/api/gates',{method:'POST',body:{name:document.querySelector('#gate-name').value,runId:document.querySelector('#gate-run').value}});dialog.close();await refresh();return toast(x.decision+': '+x.reason)}
 if(a==='source-update')return modal('Compare a candidate source snapshot',`<p>Text differences are proposals only. No new rule or mandate is automatically activated.</p><div class="field"><label for="update-title">Comparison label</label><input id="update-title" placeholder="Historical or simulated comparison"></div><div class="field"><label for="update-source">Pinned baseline</label><select id="update-source">${state.workspace.sources.map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</select></div><div class="field"><label for="update-text">Candidate extracted text</label><textarea id="update-text"></textarea></div>${button('Compare snapshots','save-update','primary')}`);
 if(a==='save-update'){await api('/api/updates',{method:'POST',body:{title:document.querySelector('#update-title').value,sourceId:document.querySelector('#update-source').value,text:document.querySelector('#update-text').value}});dialog.close();await refresh();return toast('Draft comparison saved; rule activation still requires review')}
 }catch(err){if(el.dataset.action==='normalize'){const out=document.querySelector('#mapping-result');if(out)out.innerHTML=badge('Contract violation','fail')+`<div class="notice amber space">${e(err.message)}</div>`}showError(err.message)}});
dialog.addEventListener('click',ev=>{if(ev.target===dialog)dialog.close()});
setInterval(async()=>{if(state.user&&state.page==='detail'&&state.run&&['queued','running'].includes(state.run.status)&&!dialog.open){try{state.run=await api('/api/runs/'+state.run.id);if(state.run.status==='completed')state.workspace=await api('/api/workspace');render()}catch{}}},1300);
try{const result=await api('/api/me');activateSession(result);await refresh()}catch(err){if(state.user)showError('Workspace could not load: '+err.message);else login()}

function pct(v){return v===null||v===undefined?'Not measured':v.toFixed(2)+'%'}
function gringottExplorer(){
 const connections=(state.workspace.catalog||[]).filter(c=>c.capabilities?.accounts==='mock_supported');
 if(!connections.length)return '';
 const s=state.gringott;
 return `<div class="card space"><div class="card-head"><div><h2>Mock bank API requests</h2><p>Actual HTTP calls through the selected bank adapter. Simulated consent only; no official bank connected.</p></div>${badge('mock_http')}</div><div class="pad"><div class="field"><label>Configured connection</label><select id="gringott-connection" ${s?'disabled':''}>${connections.map(c=>`<option value="${e(c.id)}" ${s?.connection===c.id?'selected':''}>${e(c.name)}</option>`).join('')}</select></div>${s?`<p>Consent expires ${date(s.expiresAt)}. Workspace refresh preserves this tab’s consent reference; server restart requires new consent.</p><div class="field"><label>Operation</label><select id="gringott-operation"><option value="accounts">Accounts</option><option value="balances">Balances</option><option value="transactions">All transaction pages</option></select></div><div class="field"><label>Account (balances / transactions)</label><select id="gringott-account">${s.accounts.map(a=>`<option value="${e(a.accountId)}">${e(a.accountId)} · ${e(a.currency)}</option>`).join('')}</select></div><div class="buttons">${button('Send request','gringott-request','primary')}${button('Revoke consent','gringott-revoke')}</div><pre class="code space" id="gringott-response">Choose an operation.</pre>`:button('Grant simulated consent','gringott-consent','primary')}<p class="footnote">Tokens are held only in server memory. To collect evidence and findings, run a mock HTTP audit from Connections or Audit center.</p></div></div>`;
}
function duration(ms){return (ms/1000).toFixed(1)+' s'}
function availabilityPanel(){const targets=state.availability||[];return '<div id="monitor-availability" tabindex="-1" class="card space"><div class="card-head"><div><h2>Synthetic API availability</h2><p>Health probes, recovery detection and persisted incident reports. Default report window: last 24 hours.</p></div>'+button('Refresh','availability-refresh','small')+'</div><div class="pad">'+(targets.length?targets.map(t=>{const r=t.report;return '<div class="detail-block space"><h3>'+e(t.name)+' '+badge(r.currentStatus,r.currentStatus==='up'?'pass':r.currentStatus==='down'?'fail':'unknown')+'</h3><p>Successful checks '+pct(r.successfulChecksPercent)+' · Estimated uptime '+pct(r.estimatedUptimePercent)+' · Coverage '+pct(r.coveragePercent)+'</p><p>'+r.checks+' probes · Estimated down '+duration(r.estimatedDownMs)+' · Unknown '+duration(r.unknownMs)+' · Last check '+date(r.lastCheck?.at)+'</p><div class="buttons">'+button('Report & export','availability-report','small','data-id="'+e(t.id)+'"')+(canConfigure()?button('Configure','availability-config','small','data-id="'+e(t.id)+'"')+button('Probe now','availability-probe','small','data-id="'+e(t.id)+'"'):'')+(t.canSwitch?button('API OFF (timeout)','availability-switch','small','data-id="'+e(t.id)+'" data-online="false"')+button('API ON','availability-switch','small','data-id="'+e(t.id)+'" data-online="true"'):'')+'</div></div>'}).join(''):'<p>No synthetic targets configured by the server operator. Existing readiness schedules do not collect availability measurements.</p>')+'</div></div>'}

setInterval(async()=>{if(state.user&&state.page==='monitor'&&!dialog.open){try{const x=await api('/api/availability');if(state.user&&state.page==='monitor'){state.availability=x.targets||[];render()}}catch{}}},5000);

document.addEventListener('toggle',ev=>{const key=ev.target.dataset?.measurementSection;if(key)state.measurementCollapsed={...state.measurementCollapsed,[key]:!ev.target.open}},true);
